// Retailer websites and phone numbers from Energy Made Easy's retailer
// register. Regenerated by scripts/pull-plans.mjs with every daily pull, for
// every retailer that has plans on the site. lib/retailerLinks.ts uses these
// for any retailer without a hand-checked link.

export interface RetailerContact {
  website: string | null;
  phone: string | null;
}

export const RETAILER_DIRECTORY_DATE: string | null = null;
export const RETAILER_DIRECTORY: Record<string, RetailerContact> = {};
